SELECT p.id, p.organisation_id,
       count(*) FILTER (WHERE t.is_required) AS required_tasks,
       count(*) FILTER (WHERE t.completed_at IS NOT NULL) AS completed_tasks,
       count(*) FILTER (WHERE t.completed_at IS NULL AND t.due_date < current_date) AS overdue_tasks
  FROM onboarding_plan p
  JOIN onboarding_plan_task t ON t.onboarding_plan_id = p.id AND t.deleted_at IS NULL
 WHERE p.deleted_at IS NULL
 GROUP BY p.id, p.organisation_id;
-- @@
CREATE OR REPLACE VIEW vw_client_vendor_submission AS
SELECT id, workforce_request_id, msp_vendor_id, candidate_profile_id, vendor_submission_status_id, proposed_bill_rate, currency_id, available_from_date FROM vendor_submission WHERE deleted_at IS NULL;
-- @@
CREATE OR REPLACE VIEW vw_staffing_margin AS
SELECT id, agency_organisation_id, bill_rate - pay_rate AS margin, (bill_rate - pay_rate) / NULLIF(bill_rate,0) * 100 AS margin_percent FROM staffing_assignment WHERE deleted_at IS NULL;
-- @@
CREATE OR REPLACE VIEW vw_timesheet_pending_approval AS
SELECT t.* , a.client_organisation_id, a.supervisor_app_user_id FROM timesheet t JOIN staffing_assignment a ON a.id = t.staffing_assignment_id WHERE t.submitted_at IS NOT NULL AND t.locked_at IS NULL;
-- @@
-- Registrations, decided, selected per drive and institution for TPO reports.
-- OVERRIDE reason: the security text requires small counts (< 5 registrations) to be suppressed; the sketch exposed them.
-- Suppressed cells show NULL counts with is_suppressed = true; withdrawn/deleted registrations excluded.
CREATE OR REPLACE VIEW vw_drive_funnel AS
SELECT placement_drive_id, institution_id,
       CASE WHEN registered < 5 THEN NULL ELSE registered END AS registered,
       CASE WHEN registered < 5 THEN NULL ELSE decided END AS decided,
       CASE WHEN registered < 5 THEN NULL ELSE selected END AS selected,
       (registered < 5) AS is_suppressed
  FROM (SELECT r.placement_drive_id, r.institution_id, count(*) AS registered,
               count(d.id) FILTER (WHERE d.drive_result_decision_id IS NOT NULL) AS decided,
               count(d.id) FILTER (WHERE dd.code IN ('selected', 'ppo_issued')) AS selected
          FROM drive_registration r
          LEFT JOIN drive_result d ON d.drive_registration_id = r.id AND d.deleted_at IS NULL
          LEFT JOIN drive_result_decision dd ON dd.id = d.drive_result_decision_id
         WHERE r.deleted_at IS NULL AND r.withdrawn_at IS NULL
         GROUP BY r.placement_drive_id, r.institution_id) x;
-- @@
CREATE OR REPLACE VIEW vw_active_account_restriction AS
SELECT * FROM account_restriction WHERE lifted_at IS NULL AND starts_at <= now() AND (ends_at IS NULL OR ends_at > now());
-- @@
CREATE OR REPLACE VIEW vw_eeo_aggregate_cell_count AS
SELECT equal_opportunity_survey_id, organisation_id, count(*) responses, count(*) FILTER (WHERE declined_to_answer) declined FROM equal_opportunity_response GROUP BY 1,2 HAVING count(*) >= 10;
-- @@
-- Single demand feed across jobs and gigs (D-15).
-- OVERRIDE reason: sketch had <category>/<city>/<status>/<opened_at> placeholders. Identifiers only (no titles, no personal
-- data); soft-deleted rows hidden on both branches.
CREATE OR REPLACE VIEW vw_unified_demand AS
SELECT 'job' AS demand_type, j.id, j.organisation_id, j.job_category_id, j.primary_city_id AS city_id,
       s.code AS status_code, j.published_at AS opened_at
  FROM job_requirement j JOIN job_requirement_status s ON s.id = j.job_requirement_status_id
 WHERE j.deleted_at IS NULL
UNION ALL
SELECT 'gig', g.id, g.organisation_id, g.job_category_id, g.city_id, s.code, g.published_at
  FROM gig_request g JOIN gig_request_status s ON s.id = g.gig_request_status_id
 WHERE g.deleted_at IS NULL;
-- @@
-- Requester-facing worker card.
-- OVERRIDE reason: duplicate output names (unnamed round(..), rating_count in both tables) are aliased. Coordinates
-- rounded to 2 dp (~1 km); no KYC columns (kyc_token, kyc_verified_at, verification status), no app_user_id; listed and
-- not-deleted workers only.
CREATE OR REPLACE VIEW vw_gig_worker_public AS
SELECT p.id, p.headline, p.hourly_rate, p.daily_rate, p.currency_id, p.service_radius_km, p.home_city_id,
       round(p.home_latitude, 2) AS approx_latitude, round(p.home_longitude, 2) AS approx_longitude,
       p.rating_avg, coalesce(s.rating_count, p.rating_count) AS rating_count,
       p.completed_gig_count, p.gig_availability_status_id
  FROM gig_worker_profile p
  LEFT JOIN gig_worker_rating_summary s ON s.gig_worker_profile_id = p.id
 WHERE p.is_listed AND p.deleted_at IS NULL;
-- @@
-- Open, public, unexpired, non-deleted gig requests for browse.
-- OVERRIDE reason: sketch was "SELECT ...". Public visibility only (invite/favourites-only requests never appear);
-- requester id not exposed and coordinates rounded to 2 dp.
CREATE OR REPLACE VIEW vw_gig_open_request AS
SELECT r.id, r.organisation_id, r.title, r.description, r.job_category_id, r.gig_work_mode_id, r.gig_experience_level_id,
       r.city_id, r.country_id, round(r.latitude, 2) AS approx_latitude, round(r.longitude, 2) AS approx_longitude,
       r.window_start_at, r.window_end_at, r.gig_price_type_id, r.is_rate_based, r.fixed_price, r.rate_amount,
       r.gig_rate_unit_id, r.budget_max, r.currency_id, r.headcount, r.accepted_count, r.application_deadline_at, r.published_at
  FROM gig_request r
  JOIN gig_request_status s ON s.id = r.gig_request_status_id AND s.code = 'open'
  JOIN gig_request_visibility v ON v.id = r.gig_request_visibility_id AND v.code = 'public'
 WHERE r.deleted_at IS NULL
   AND (r.application_deadline_at IS NULL OR r.application_deadline_at > now())
   AND (r.window_end_at IS NULL OR r.window_end_at > now());
-- @@
-- Override: the sketch had the placeholders "SELECT ..." and "<public>". Public browse surface; confidential employers are hidden
-- (organisation_id / organisation_name NULL); internal columns (posted_by, created_by, legacy refs) are not exposed.
CREATE OR REPLACE VIEW vw_live_job_requirement AS
SELECT r.id, r.reference_code, r.title, r.short_summary, r.description, r.description_language_id,
       r.job_role_id, r.job_category_id, r.employment_type_id, r.work_type_id, r.seniority_level_id, r.industry_id,
       r.shift_type_id, r.hiring_urgency_id, r.apply_mode_id, r.external_apply_url,
       r.primary_country_id, r.primary_city_id,
       r.salary_min, r.salary_max, r.currency_id, r.salary_period_id, r.salary_disclosure_id,
       r.experience_min_months, r.experience_max_months, r.openings_count,
       r.is_open_to_freshers, r.is_walk_in, r.is_confidential_employer,
       CASE WHEN r.is_confidential_employer THEN NULL ELSE r.organisation_id END AS organisation_id,
       CASE WHEN r.is_confidential_employer THEN NULL ELSE o.display_name END AS organisation_name,
       r.published_at, r.expires_at, r.closing_date,
       s.application_count, s.view_count,
       (SELECT count(*) FROM job_requirement_location l WHERE l.job_requirement_id = r.id) AS location_count
FROM job_requirement r
JOIN visibility_level vl ON vl.id = r.visibility_level_id AND vl.code = 'public'
LEFT JOIN organisation o ON o.id = r.organisation_id AND o.deleted_at IS NULL
LEFT JOIN job_requirement_stat s ON s.job_requirement_id = r.id
WHERE r.is_live AND r.deleted_at IS NULL AND r.closed_at IS NULL
  AND (r.expires_at IS NULL OR r.expires_at > now());
-- @@
-- Override: the sketch joined job_consultant_openness.deleted_at, a column that table does not have. consultant_job_openness (sourcing)
-- is authoritative (Findings F-04), so this view is a thin alias: live requirements open to consultants with a valid general window
-- (jobs-side scope all_consultants, or sourcing-side window with no personal consultant). Personal invitations are only visible
-- through vw_consultant_open_requirement / fn_consultant_open_requirement.
CREATE OR REPLACE VIEW vw_consultant_job_requirement AS
SELECT r.*
FROM job_requirement r
WHERE r.is_open_to_consultants AND r.is_live AND r.deleted_at IS NULL
  AND (EXISTS (SELECT 1 FROM job_consultant_openness o
               JOIN consultant_access_scope sc ON sc.id = o.consultant_access_scope_id AND sc.code = 'all_consultants'
               WHERE o.job_requirement_id = r.id AND o.valid_from <= now() AND (o.valid_to IS NULL OR o.valid_to > now()))
    OR EXISTS (SELECT 1 FROM consultant_job_openness co
               WHERE co.job_requirement_id = r.id AND co.consultant_profile_id IS NULL AND co.closed_at IS NULL AND co.deleted_at IS NULL
                 AND co.valid_from <= now() AND (co.valid_to IS NULL OR co.valid_to > now())));
-- @@
CREATE OR REPLACE VIEW vw_application_pipeline AS
SELECT job_requirement_id, application_status_id, count(*) FROM job_application WHERE deleted_at IS NULL AND withdrawn_at IS NULL GROUP BY 1,2;
-- @@
CREATE OR REPLACE VIEW vw_login_history AS
SELECT la.app_user_id, la.attempted_at, la.login_outcome_id, la.ip_address, d.device_platform_id, ds.ended_at, ds.session_end_reason_id FROM login_attempt la LEFT JOIN device d ON d.id = la.device_id LEFT JOIN device_session ds ON ds.device_id = la.device_id AND ds.started_at >= la.attempted_at AND ds.started_at < la.attempted_at + interval '1 minute' WHERE la.app_user_id IS NOT NULL;
-- @@
CREATE OR REPLACE VIEW vw_active_device_session AS
SELECT * FROM device_session WHERE ended_at IS NULL AND expires_at > now();
-- @@
CREATE OR REPLACE VIEW vw_licence_seat_availability AS
SELECT l.id, l.max_users, count(s.id) AS used FROM licence l LEFT JOIN licence_seat s ON s.licence_id = l.id AND s.revoked_at IS NULL AND s.deleted_at IS NULL GROUP BY l.id;
-- @@
CREATE OR REPLACE VIEW vw_notification_delivery_latest AS
SELECT d.id, d.notification_id, d.notification_channel_id, (array_agg(s.code ORDER BY s.precedence DESC))[1] AS status_code FROM notification_delivery d JOIN (SELECT notification_delivery_id, delivery_status_id FROM notification_delivery_event UNION ALL SELECT id, delivery_status_id FROM notification_delivery) e ON e.notification_delivery_id = d.id JOIN delivery_status s ON s.id = e.delivery_status_id GROUP BY d.id, d.notification_id, d.notification_channel_id;
-- @@
CREATE OR REPLACE VIEW vw_unread_notification_count AS
SELECT recipient_app_user_id, count(*) AS unread_count FROM notification WHERE read_at IS NULL AND expires_at > now() GROUP BY recipient_app_user_id;
-- @@
-- Candidates a recruiter organisation may see in search.
-- OVERRIDE reason (privacy bug): the sketch LEFT JOINed privacy_hidden_organisation, giving one row per hidden org, so a
-- candidate hidden from orgs A and B still showed up as the row (B) to a recruiter of org A. Hidden orgs are now an array
-- (hidden_from_organisation_ids); the caller filters `NOT (:org = ANY(hidden_from_organisation_ids))`. Also requires
-- an existing, non-deleted, non-anonymised, searchable profile.
CREATE OR REPLACE VIEW vw_recruiter_searchable_candidate AS
SELECT p.app_user_id, c.id AS candidate_profile_id, p.profile_visibility_level_id,
       coalesce((SELECT array_agg(h.organisation_id) FROM privacy_hidden_organisation h WHERE h.app_user_id = p.app_user_id),
                ARRAY[]::UUID[]) AS hidden_from_organisation_ids
  FROM privacy_setting p
  JOIN candidate_profile c ON c.app_user_id = p.app_user_id AND c.deleted_at IS NULL AND c.anonymised_at IS NULL AND c.is_searchable
 WHERE p.is_searchable_by_recruiters;
-- @@
CREATE OR REPLACE VIEW vw_support_ticket_sla_breach AS
SELECT id, ticket_number, resolution_due_at FROM support_ticket WHERE resolved_at IS NULL AND deleted_at IS NULL AND (resolution_due_at < now() OR (first_responded_at IS NULL AND first_response_due_at < now()));
-- @@
CREATE OR REPLACE VIEW vw_recruiter_job_requirement AS
SELECT m.recruiter_app_user_id AS viewer_app_user_id, jr.*, m.id AS recruiter_organisation_mapping_id
FROM job_requirement jr
JOIN organisation_hierarchy_closure c ON c.descendant_organisation_id = jr.organisation_id
JOIN recruiter_organisation_mapping m ON m.organisation_id = c.ancestor_organisation_id
     AND m.effective_from <= now() AND (m.effective_to IS NULL OR m.effective_to > now())
     AND (c.depth = 0 OR m.mapping_scope_id = (SELECT id FROM mapping_scope WHERE code = 'with_descendants'))
JOIN organisation o ON o.id = m.organisation_id AND o.deleted_at IS NULL
     AND o.organisation_status_id = (SELECT id FROM organisation_status WHERE code = 'active')
WHERE jr.deleted_at IS NULL;
CREATE OR REPLACE FUNCTION fn_recruiter_job_requirement(p_viewer_app_user_id UUID) RETURNS SETOF vw_recruiter_job_requirement
LANGUAGE SQL STABLE AS $$ SELECT * FROM vw_recruiter_job_requirement WHERE viewer_app_user_id = p_viewer_app_user_id $$;
-- @@
CREATE OR REPLACE VIEW vw_organisation_public AS
SELECT o.id, o.slug, o.display_name, o.tagline, o.website_url, o.description, o.organisation_size_band_id, o.primary_industry_id, o.founded_year, o.verification_status_id, o.logo_object_ref FROM organisation o WHERE o.deleted_at IS NULL AND o.visibility_level_id = (SELECT id FROM visibility_level WHERE code='public');
-- @@
CREATE OR REPLACE VIEW vw_organisation_review_public AS
SELECT r.id, r.organisation_id, r.rating_overall, r.title, r.pros, r.cons, r.published_at, resp.body AS response_body FROM organisation_review r LEFT JOIN organisation_review_response resp ON resp.organisation_review_id = r.id AND resp.is_published AND resp.deleted_at IS NULL WHERE r.is_published AND r.deleted_at IS NULL;
-- @@
CREATE OR REPLACE VIEW vw_account_active_admin AS
SELECT a.account_id, a.admin_app_user_id, a.account_admin_level_id FROM account_admin a WHERE a.effective_to IS NULL;
-- @@
-- Override: the sketch was not viewer-aware (AT-05 requires blocked parties to get 0 rows from this card too) and its INNER JOIN on
-- salary_disclosure dropped candidates without a disclosure. Now a pair view over vw_candidate_visible_to_user (filter on
-- viewer_app_user_id or use fn_candidate_profile_recruiter); salary and contact are NULL (not 0/empty) unless disclosed / visible;
-- birth_date, address and the other Sensitive columns are never exposed.
CREATE OR REPLACE VIEW vw_candidate_profile_recruiter AS
SELECT vis.viewer_app_user_id, p.id, p.display_name, p.headline,
       CASE WHEN d.code = 'disclosed' THEN p.current_salary_amount END AS current_salary_amount,
       CASE WHEN p.is_contact_visible_to_recruiters THEN p.contact_email END AS contact_email
FROM vw_candidate_visible_to_user vis
JOIN candidate_profile p ON p.id = vis.candidate_profile_id AND p.deleted_at IS NULL AND p.is_searchable
LEFT JOIN salary_disclosure d ON d.id = p.current_salary_disclosure_id;
-- @@
CREATE OR REPLACE VIEW vw_candidate_search_document AS
SELECT p.id, p.headline, p.current_city_id, array_agg(s.skill_id) AS skill_ids FROM candidate_profile p LEFT JOIN candidate_skill s ON s.candidate_profile_id=p.id AND s.deleted_at IS NULL WHERE p.is_searchable AND p.deleted_at IS NULL GROUP BY p.id;
-- @@
-- Override: the sketch called current_consultant_profile() (a session function that does not exist; the viewer is an explicit
-- argument by design). Pair view (viewer_consultant_profile_id, window); read through fn_consultant_open_requirement(p_consultant_profile_id)
-- or WHERE viewer_consultant_profile_id = $1. Also requires the requirement itself to be live and open to consultants (AT-03).
CREATE OR REPLACE VIEW vw_consultant_open_requirement AS
SELECT cp.id AS viewer_consultant_profile_id, o.*, jr.title AS job_title, jr.reference_code AS job_reference_code
FROM consultant_job_openness o
JOIN job_requirement jr ON jr.id = o.job_requirement_id AND jr.is_live AND jr.is_open_to_consultants AND jr.deleted_at IS NULL
JOIN consultant_profile cp ON cp.deleted_at IS NULL AND (o.consultant_profile_id IS NULL OR o.consultant_profile_id = cp.id)
WHERE o.closed_at IS NULL AND o.deleted_at IS NULL AND o.valid_from <= now() AND (o.valid_to IS NULL OR o.valid_to > now());
-- @@
-- Override: the sketch used the parameters $sender/$org and a non-existent user_block.candidate_profile_id. Pair view over
-- vw_candidate_visible_to_user (user + organisation blocks, both directions, effective-dated): one row per (sender, candidate)
-- that may be contacted: not blocked, consent not withdrawn/expired (latest profile_visible_to_employers / share_with_consultants
-- event), searchable, and not contacted by the same sender in the last 7 days. id = candidate_profile_id (BR-SRC-06).
-- Use WHERE sender_app_user_id = $1 or fn_outreach_eligible_candidate(sender).
CREATE OR REPLACE VIEW vw_outreach_eligible_candidate AS
SELECT vis.viewer_app_user_id AS sender_app_user_id, vis.candidate_profile_id AS id, vis.candidate_app_user_id
FROM vw_candidate_visible_to_user vis
JOIN candidate_profile cp ON cp.id = vis.candidate_profile_id AND cp.is_searchable AND cp.anonymised_at IS NULL
WHERE NOT EXISTS (SELECT 1 FROM vw_user_consent_current cc
                  JOIN consent_type ct ON ct.id = cc.consent_type_id AND ct.code IN ('profile_visible_to_employers','share_with_consultants')
                  JOIN consent_action ca ON ca.id = cc.consent_action_id AND ca.code IN ('withdrawn','expired')
                  WHERE cc.app_user_id = vis.candidate_app_user_id)
  AND NOT EXISTS (SELECT 1 FROM candidate_contact_attempt a
                  WHERE a.candidate_profile_id = vis.candidate_profile_id AND a.contacter_app_user_id = vis.viewer_app_user_id
                    AND a.attempted_at > now() - INTERVAL '7 days');
-- @@
CREATE OR REPLACE VIEW vw_sourcing_request_summary AS
SELECT sr.id, count(ss.id) AS submissions FROM sourcing_request sr LEFT JOIN sourcing_submission ss ON ss.sourcing_request_id = sr.id GROUP BY sr.id;
-- @@
CREATE OR REPLACE VIEW vw_subscription_period_overlap AS
SELECT a.licence_id, a.id AS period_a, b.id AS period_b FROM subscription_period a JOIN subscription_period b ON a.licence_id=b.licence_id AND a.id < b.id AND a.period_start_date < b.period_end_date AND b.period_start_date < a.period_end_date WHERE a.period_start_date < a.period_end_date AND b.period_start_date < b.period_end_date;
-- @@
CREATE OR REPLACE VIEW vw_wallet_balance_drift AS
SELECT w.id, w.credit_balance, SUM(l.credits_delta) AS ledger_sum, w.ledger_sequence, MAX(l.sequence_no) AS max_seq FROM wallet w LEFT JOIN wallet_ledger_entry l ON l.wallet_id=w.id GROUP BY w.id, w.credit_balance, w.ledger_sequence HAVING w.credit_balance <> COALESCE(SUM(l.credits_delta),0) OR w.ledger_sequence <> COALESCE(MAX(l.sequence_no),0);
-- @@
CREATE OR REPLACE VIEW vw_invoice_number_gap AS
SELECT invoice_number_series_id, MAX(invoice_number) - COUNT(*) AS missing FROM invoice WHERE invoice_number IS NOT NULL GROUP BY invoice_number_series_id HAVING MAX(invoice_number) <> COUNT(*);
-- @@
CREATE OR REPLACE VIEW vw_organisation_download_spend AS
SELECT organisation_id, date_trunc('day', downloaded_at) AS day, COUNT(*) AS downloads, SUM(credits_charged) AS credits FROM profile_download GROUP BY 1,2;
-- @@
-- Override: the sketch used a plain join which duplicated each benchmark once per source, and kept sources that were inactive/deleted.
-- One row per publishable benchmark with at least one fresh active source; attribution texts aggregated; age exposed.
CREATE OR REPLACE VIEW vw_salary_benchmark_published AS
SELECT b.*, string_agg(s.attribution_text, '; ' ORDER BY s.attribution_text) AS attribution_text,
       count(s.id) AS fresh_source_count, now() - b.refreshed_at AS benchmark_age
FROM salary_benchmark b
JOIN salary_benchmark_source x ON x.salary_benchmark_id = b.id
JOIN reference_data_source s ON s.id = x.reference_data_source_id AND s.deleted_at IS NULL AND s.is_active
WHERE b.is_publishable AND now() - b.refreshed_at <= coalesce(s.max_staleness_days, 36500) * INTERVAL '1 day'
GROUP BY b.id;
-- @@
CREATE OR REPLACE VIEW vw_company_rating_latest AS
SELECT DISTINCT ON (organisation_id, reference_data_source_id) * FROM company_rating_snapshot WHERE is_displayable ORDER BY organisation_id, reference_data_source_id, snapshot_date DESC;
-- @@
CREATE OR REPLACE VIEW vw_feature_flag_effective AS
SELECT f.flag_key, f.default_enabled, r.* FROM feature_flag f LEFT JOIN feature_flag_rule r ON r.feature_flag_id = f.id WHERE f.deleted_at IS NULL;
